            Map<Long, List<String>> lines = log.onSheet(sheetId);
            return claims.onSheet(sheetId).stream()
                    .map(c -> ClaimResponse.from(c, figures, lines.getOrDefault(c.getId(), List.of()))).toList();
        }));
    }
}

